 "content": "def transform(grid):
    """Mark the trailing empty cells of a repeated, truncated line-pattern."""
    if not grid:
        return []
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])

    # Detect row-pattern copies separated by all-background bands. The example
    # has four patterned rows repeated lower down; in each later block, the
    # rightmost three background cells of each patterned row become 1s.
    def blank(row):
        return all(v == bg for v in row)

    # Partition into contiguous bands of nonblank rows (ignore blank rows).
    bands = []
    r = 0
    while r < h:
        if blank(grid[r]):
            r += 1
            continue
        start = r
        rows = []
        while r < h and not blank(grid[r]):
            rows.append(r)
            r += 1
        bands.append(rows)

    if len(bands) < 2:
        return out
    # First band defines the repeating row motif; later matching bands are
    # copies and their right-side added blank area is painted with 1.
    base_rows = bands[0]
    base = [grid[i] for i in base_rows]
    for rows in bands[1:]:
        if len(rows) != len(base):
            continue
        for ri, r in enumerate(rows):
            if grid[r] != base[ri]:
                # Accept only when the foreground pattern matches and differs
                # by a uniform appended suffix of background cells.
                row = grid[r]
                templ = base[ri]
                if any((a != bg and b != a) for a, b in zip(templ, row)):
                    continue
                # Mark the suffix at far right, at least three cells if empty.
                c = w - 1
                while c >= 0 and row[c] == bg and templ[c] == bg:
                    c -= 1
                suffix = w - 1 - c
                if suffix >= 3:
                    for x in range(w - 3, w):
                        if row[x] == bg:
                            out[r][x] = 1
    return out
